            .collect();
        let raccolta = extensions::collect_geometries(&gruppo).map_err(|e| del_kernel(op, &e))?;
        raccolte.push(raccolta.as_ref().map(encode_geometry).transpose()?);
        let prima = righe
            .first()
            .copied()
            .ok_or_else(|| PlenoraError::Internal(format!("{op}: gruppo senza righe")))?;
        rappresentanti.push(
            u64::try_from(prima)
                .map_err(|_| PlenoraError::Internal(format!("{op}: riga non rappresentabile")))?,
        );
    }

for &indice in chiavi {
        let colonna = batch.columns().get(indice).ok_or_else(|| {
            PlenoraError::Internal(format!("{op}: colonna chiave oltre lo schema"))
        })?;
        colonne.push(take(colonna.as_ref(), &indici, None)?);
    }

for (posizione, &indice) in chiavi.iter().enumerate() {
        let colonna = batch.columns().get(indice).ok_or_else(|| {
            PlenoraError::Internal(format!("{op}: colonna chiave oltre lo schema"))
        })?;
        // Nomi posizionali: nessuna collisione con l'indice ne' fra chiavi.
        let nome = format!("k{posizione}");
        campi.push(Field::new(&nome, colonna.data_type().clone(), true));
        colonne.push(Arc::clone(colonna));
        nomi.push(nome);
    }

for posizione in 0..ordinata.num_rows() {
        let riga = usize::try_from(indici.value(posizione))
            .map_err(|_| PlenoraError::Internal(format!("{op}: riga non rappresentabile")))?;
        let stesso_gruppo = match posizione.checked_sub(1) {
            None => false,
            Some(precedente) => {
                let mut uguali = true;
                for colonna in &ordinata.columns()[..chiavi.len()] {
                    if plenora_kernels_table::aggregation::compare_cells_typed(
                        colonna, precedente, colonna, posizione,
                    )? != std::cmp::Ordering::Equal
                    {
                        uguali = false;
                        break;
                    }
                }
                uguali
            }
        };
        match gruppi.last_mut() {
            Some(gruppo) if stesso_gruppo => gruppo.push(riga),
            _ => gruppi.push(vec![riga]),
        }
    }

for colonna in &ordinata.columns()[..chiavi.len()] {
                    if plenora_kernels_table::aggregation::compare_cells_typed(
                        colonna, precedente, colonna, posizione,
                    )? != std::cmp::Ordering::Equal
                    {
                        uguali = false;
                        break;
                    }
                }

while inizio < righe {
        let fine = (inizio + RIGHE_IN_VOLO).min(righe);
        let per_riga = (margine.byte_disponibili() - usati) / RIGHE_IN_VOLO as u64;
        let fetta = celle.slice(inizio, fine - inizio);
        let blocco = map_nullable(&fetta, |payload| {
            // Prima di decodificare, dalle intestazioni del WKB.
            MargineMemoria::byte(per_riga)
                .verifica(plenora_kernels_geo::decoded_size::decoded_size_xy(payload).unwrap_or(0))
                .map_err(oltre)?;
            let geometria = plenora_kernels_geo::wkb_decoder::decode_validated(payload)?;
            // La geometria decodificata vive per tutta la riga.
            let decodificata = byte_heap_geometria(&geometria);
            MargineMemoria::byte(per_riga)
                .verifica(decodificata)
                .map_err(oltre)?;
            kernel(&geometria, MargineMemoria::byte(per_riga - decodificata))?
                .map(|risultato| encode_geometry(&risultato))
                .transpose()
        })?;
        for risultato in blocco {
            if let Some(wkb) = &risultato {
                // La cella (capacita' vera) e la sua copia nella colonna.
                usati = usati
                    .saturating_add(u64::try_from(wkb.capacity()).unwrap_or(u64::MAX))
                    .saturating_add(u64::try_from(wkb.len()).unwrap_or(u64::MAX));
                margine.verifica(usati).map_err(oltre)?;
            }
            uscita.push(risultato);
        }
        inizio = fine;
    }

for risultato in blocco {
            if let Some(wkb) = &risultato {
                // La cella (capacita' vera) e la sua copia nella colonna.
                usati = usati
                    .saturating_add(u64::try_from(wkb.capacity()).unwrap_or(u64::MAX))
                    .saturating_add(u64::try_from(wkb.len()).unwrap_or(u64::MAX));
                margine.verifica(usati).map_err(oltre)?;
            }
            uscita.push(risultato);
        }

for asse in 0..4 {
                    colonne.push(Arc::new(Float64Array::from(
                        limiti
                            .iter()
                            .map(|valore| valore.map(|limite| limite[asse]))
                            .collect::<Vec<_>>(),
                    )));
                }

for campo in scelti {
                    colonne.push(colonna_accessoria(*campo, &accessori));
                }

for (x, y) in xs.into_iter().zip(ys) {
        let (Some(x), Some(y)) = (x, y) else {
            return Err(PlenoraError::InvalidPlan(format!(
                "{op}: coordinata null: la colonna geometria prodotta non ammette null"
            )));
        };
        let punto = construction::point_from_lon_lat(x, y).map_err(|e| del_kernel(op, &e))?;
        nel_dominio(op, &punto, crs)?;
        celle.push(Some(encode_geometry(&punto)?));
    }

for riga in 0..celle.len() {
        if celle.is_null(riga) {
            continue;
        }
        match tipo_wkb(celle.value(riga)) {
            Some(tipo) if ammessi.contains(&tipo) => {}
            _ => return Err(()),
        }
    }

for geometria in &uscita.geometries {
        let indice = uscita.schema.index_of(&geometria.name).map_err(|_| {
            PlenoraError::Internal(format!(
                "{op}: geometria del contratto assente dallo schema"
            ))
        })?;
        let celle = colonne
            .get(indice)
            .and_then(|colonna| colonna.as_any().downcast_ref::<BinaryArray>())
            .ok_or_else(|| {
                PlenoraError::Internal(format!("{op}: colonna geometria calcolata non Binary"))
            })?;
        if !geometria.nullable && celle.null_count() > 0 {
            return Err(PlenoraError::InvalidPlan(format!(
                "{op}: il risultato di una riga e' vuoto (null), ma la colonna geometria \
                 `{}` del contratto non ammette null",
                geometria.name
            )));
        }
        verifica_tipi_dichiarati(celle, tipi_con_elenco(geometria).as_deref()).map_err(|()| {
            PlenoraError::Internal(format!(
                "{op}: una geometria prodotta ha un tipo che il contratto d'uscita non \
                     dichiara (analisi e kernel divergono)"
            ))
        })?;
    }

for batch_arrow in ingressi {
            plenora_core::valida_arrow::batch(batch_arrow)?;
        }

for (lato, batch) in self.lati.iter().zip(ingressi) {
            if let Some(lato) = lato {
                lato.verifica(self.op, batch)?;
            }
        }

for passo in &piano.steps {
        let byte_config = serde_json::to_vec(&passo.config)
            .map_err(|_| PlenoraError::InvalidPlan("config non serializzabile".to_owned()))?
            .len();
        oltre(
            &format!("passo `{}`: max_config_bytes_per_node", passo.out),
            byte_config,
            limiti.max_config_bytes_per_node,
        )?;
        let mut livello = 0;
        for sorgente in &passo.inputs {
            let uso = consumatori.entry(sorgente).or_insert(0);
            *uso += 1;
            oltre(
                &format!("`{sorgente}`: max_fan_out"),
                *uso,
                limiti.max_fan_out,
            )?;
            livello = livello.max(profondita.get(sorgente.as_str()).copied().unwrap_or(0));
        }
        let livello = livello + 1;
        oltre(
            &format!("passo `{}`: max_plan_depth", passo.out),
            livello,
            limiti.max_plan_depth,
        )?;
        profondita.insert(&passo.out, livello);
    }

for sorgente in &passo.inputs {
            let uso = consumatori.entry(sorgente).or_insert(0);
            *uso += 1;
            oltre(
                &format!("`{sorgente}`: max_fan_out"),
                *uso,
                limiti.max_fan_out,
            )?;
            livello = livello.max(profondita.get(sorgente.as_str()).copied().unwrap_or(0));
        }

for (before, after) in contratto.schema.fields().iter().zip(schema.fields()) {
        let key = plenora_core::contract::arrow_metadata::PLENORA_FIELD_ID_KEY;
        if before.metadata().get(key) != after.metadata().get(key) {
            let id = contratto
                .field_ids
                .get(before.name())
                .copied()
                .ok_or_else(|| {
                    PlenoraError::Schema("identita' logica assente durante l'emissione".into())
                })?;
            if campi.public_identity(id).is_none() {
                campi.record_public_identity(id, before.metadata().get(key).cloned());
            }
        }
    }

for nome in &self.inputs {
            verifica_nome(nome, "input", &limiti_piano)?;
            if !definiti.insert(nome.as_str()) {
                return Err(PlenoraError::InvalidPlan(format!(
                    "input `{nome}` dichiarato due volte"
                )));
            }
        }

for passo in &self.steps {
            verifica_nome(&passo.out, "passo", &limiti_piano)?;
            for sorgente in &passo.inputs {
                if !definiti.contains(sorgente.as_str()) {
                    return Err(PlenoraError::InvalidPlan(format!(
                        "passo `{}`: `{sorgente}` non e' definito prima del passo",
                        passo.out
                    )));
                }
            }
            if !definiti.insert(passo.out.as_str()) {
                return Err(PlenoraError::InvalidPlan(format!(
                    "`{}` e' gia' definito: ogni nome si definisce una volta sola",
                    passo.out
                )));
            }
        }

for sorgente in &passo.inputs {
                if !definiti.contains(sorgente.as_str()) {
                    return Err(PlenoraError::InvalidPlan(format!(
                        "passo `{}`: `{sorgente}` non e' definito prima del passo",
                        passo.out
                    )));
                }
            }

for nome in &self.outputs {
            if !definiti.contains(nome.as_str()) {
                return Err(PlenoraError::InvalidPlan(format!(
                    "output `{nome}` non definito dal piano"
                )));
            }
            if !dichiarati.insert(nome.as_str()) {
                return Err(PlenoraError::InvalidPlan(format!(
                    "output `{nome}` dichiarato due volte"
                )));
            }
        }

for (nome, schema) in schemas {
            if forniti.insert(nome, schema).is_some() {
                return Err(PlenoraError::InvalidPlan(format!(
                    "schema di input duplicato per `{nome}`"
                )));
            }
        }

for dichiarato in &self.inputs {
            if !forniti.contains_key(dichiarato.as_str()) {
                return Err(PlenoraError::InvalidPlan(format!(
                    "manca lo schema dell'input `{dichiarato}`"
                )));
            }
        }

for nome in &self.inputs {
            let schema = forniti.get(nome.as_str()).ok_or_else(|| {
                PlenoraError::Internal("schema di input non risolto dopo il controllo".to_owned())
            })?;
            let normalizzato = normalizza_schema(schema);
            let mut letto = contract_from_arrow_schema(normalizzato.clone(), resolve_crs)
                .map_err(|errore| errore.con_contesto(&format!("input `{nome}`")))?;
            letto
                .validate()
                .map_err(|errore| errore.con_contesto(&format!("input `{nome}`")))?;
            for id in verifica_identita_campi(&normalizzato)
                .map_err(|errore| errore.con_contesto(&format!("input `{nome}`")))?
            {
                if !identita_osservate.insert(id) {
                    identita_ambigue.insert(id);
                }
            }
            if let Some(ordinamento) = &letto.properties.sorted_by {
                if ordinamento.confidence.value().is_some() {
                    return Err(PlenoraError::InvalidPlan(format!(
                        "l'input `{nome}` dichiara sorted_by con chiavi FieldId: il namespace \
                         dei FieldId e' assegnato dal runner e le chiavi non sono riferibili \
                         a colonne"
                    )));
                }
            }
            let mut rimappatura = BTreeMap::new();
            for geometria in &letto.geometries {
                rimappatura.insert(geometria.field_id, campi.alloc()?);
            }
            letto.active_geometry = letto
                .active_geometry
                .map(|id| {
                    rimappatura
                        .get(&id)
                        .copied()
                        .ok_or_else(|| PlenoraError::Schema("primaria senza corrispondenza".into()))
                })
                .transpose()?;
            for geometria in &mut letto.geometries {
                geometria.field_id = *rimappatura
                    .get(&geometria.field_id)
                    .ok_or_else(|| PlenoraError::Schema("geometria senza corrispondenza".into()))?;
                letto
                    .field_ids
                    .insert(geometria.name.clone(), geometria.field_id);
            }
            // Identita' logica anche per gli attributi: un passthrough non e'
            // una derivazione nuova solo perche' il campo non e' geometrico.
            for field in letto.schema.fields() {
                if !letto.field_ids.contains_key(field.name()) {
                    letto.field_ids.insert(field.name().clone(), campi.alloc()?);
                }
            }
            verifica_colonne(&letto, limiti_kernel.max_columns)
                .map_err(|errore| nel_passo_o_input(&format!("input `{nome}`"), errore))?;
            letto = canonico(letto, &mut campi)
                .map_err(|errore| nel_passo_o_input(&format!("input `{nome}`"), errore))?;
            schemi_input.insert(nome.clone(), normalizzato);
            contratti.insert(nome.clone(), letto);
            provenance.insert(nome.clone(), true);
        }

for id in verifica_identita_campi(&normalizzato)
                .map_err(|errore| errore.con_contesto(&format!("input `{nome}`")))?
            {
                if !identita_osservate.insert(id) {
                    identita_ambigue.insert(id);
                }
            }

for geometria in &letto.geometries {
                rimappatura.insert(geometria.field_id, campi.alloc()?);
            }

for geometria in &mut letto.geometries {
                geometria.field_id = *rimappatura
                    .get(&geometria.field_id)
                    .ok_or_else(|| PlenoraError::Schema("geometria senza corrispondenza".into()))?;
                letto
                    .field_ids
                    .insert(geometria.name.clone(), geometria.field_id);
            }

for field in letto.schema.fields() {
                if !letto.field_ids.contains_key(field.name()) {
                    letto.field_ids.insert(field.name().clone(), campi.alloc()?);
                }
            }

for passo in &self.steps {
            let descrittore = find_operation(&passo.op).ok_or_else(|| {
                nel_passo(
                    &passo.out,
                    PlenoraError::Unsupported(format!("{}: operazione sconosciuta", passo.op)),
                )
            })?;
            let geo = descrittore.family == Family::Geo;
            verifica_arieta(descrittore, passo.inputs.len())
                .map_err(|errore| nel_passo(&passo.out, errore))?;
            let preparato = if geo {
                None
            } else {
                Some(
                    PassoPreparato::prepara(descrittore.id, &passo.config)
                        .map_err(|errore| nel_passo(&passo.out, errore))?,
                )
            };
            // Il budget si applica a ogni passo: un'operazione senza modello
            // di costo non ha una previsione, e non si esegue.
            let costo = costo_di(descrittore.id).ok_or_else(|| {
                nel_passo(
                    &passo.out,
                    PlenoraError::Unsupported(format!(
                        "{}: operazione senza modello di costo per il budget di memoria",
                        descrittore.id
                    )),
                )
            })?;

            // Diagnostiche per riga: gli indici del kernel sono righe del suo
            // primo ingresso (per `assert_foreign_key` il lato left, per le
            // unarie l'unico). Sono righe della sorgente solo se nessun passo
            // a monte ha cambiato numero o ordine delle righe; altrimenti il
            // runner pubblica i soli conteggi. Nessuna catena si rifiuta per
            // questo.
            let righe_della_sorgente = passo
                .inputs
                .first()
                .is_some_and(|sorgente| provenance.get(sorgente).copied().unwrap_or(false));
            let base_indici = if righe_della_sorgente {
                BaseIndici::Sorgente
            } else {
                BaseIndici::SenzaAttribuzione
            };
            let ingressi: Vec<DataContract> = passo
                .inputs
                .iter()
                .map(|sorgente| {
                    contratti.get(sorgente).cloned().ok_or_else(|| {
                        PlenoraError::Internal(format!(
                            "contratto di `{sorgente}` non risolto dalla validazione"
                        ))
                    })
                })
                .collect::<Result<_>>()?;
            let moltiplicatore_dichiarato = match (&preparato, ingressi.first()) {
                (Some(preparato), Some(primo)) => {
                    preparato.moltiplicatore_dichiarato(&primo.schema)
                }
                _ => None,
            };
            let (uscita, kernel, righe_previste) = if let Some(preparato) = preparato {
                let uscita = analyze_table_contract(
                    descrittore.id,
                    &ingressi,
                    &passo.config,
                    &mut campi,
                    &limiti_kernel,
                )
                .map_err(|errore| nel_passo(&passo.out, errore))?;
                verifica_ambiente(&preparato).map_err(|errore| nel_passo(&passo.out, errore))?;
                (uscita, KernelPasso::Tabellare(preparato), 0)
            } else {
                let uscita = analyze_geo_contract(
                    descrittore.id,
                    &ingressi,
                    &passo.config,
                    crs_piano.as_ref(),
                    &mut campi,
                )
                .map_err(|errore| nel_passo(&passo.out, errore))?;
                let geo = PassoGeo::prepara(
                    descrittore,
                    &passo.config,
                    &ingressi,
                    &uscita,
                    &limiti,
                    self.outputs.contains(&passo.out),
                )
                .map_err(|errore| nel_passo(&passo.out, errore))?;
                let righe = PassoGeo::righe_previste(&uscita);
                (uscita, KernelPasso::Geo(Box::new(geo)), righe)
            };
            verifica_colonne(&uscita, limiti_kernel.max_columns)
                .map_err(|errore| nel_passo(&passo.out, errore))?;
            let uscita =
                canonico(uscita, &mut campi).map_err(|errore| nel_passo(&passo.out, errore))?;
            let effects = if geo {
                let (operands, _) = plenora_kernels_geo::analyze::resolve_operands(
                    descrittore,
                    &ingressi,
                    &passo.config,
                )?;
                policy::contract_column_effects(descrittore, &uscita, &operands)?
            } else {
                policy::column_effects(descrittore, &uscita.schema, &[])?
            };
            let effetti_localizzati = policy::report::localized_effects(
                descrittore,
                &ingressi.iter().collect::<Vec<_>>(),
                &uscita,
                &effects,
            )?;
            let colonne_uscita = u64::try_from(uscita.schema.fields().len()).unwrap_or(u64::MAX);
            contratti.insert(passo.out.clone(), uscita);
            // Un'operazione che conserva le righe conserva quelle del primo
            // ingresso: `assert_foreign_key` rende il lato left invariato.
            provenance.insert(
                passo.out.clone(),
                righe_della_sorgente
                    && descrittore.source_row_provenance() == SourceRowProvenance::Preserved,
            );
            passi.push(PassoValidato {
                out: passo.out.clone(),
                descrittore,
                inputs: passo.inputs.clone(),
                kernel,
                costo,
                righe_previste,
                base_indici,
                colonne_uscita,
                moltiplicatore_dichiarato,
                effetti_localizzati,
            });
        }

for nome in &self.outputs {
            let interno = contratti.get(nome).ok_or_else(|| {
                PlenoraError::Internal(format!("contratto dell'output `{nome}` assente"))
            })?;
            let fields = interno
                .schema
                .fields()
                .iter()
                .map(|field| {
                    let mut metadata = field.metadata().clone();
                    if let Some(original) = interno
                        .field_ids
                        .get(field.name())
                        .and_then(|id| campi.public_identity(*id))
                    {
                        metadata
                            .remove(plenora_core::contract::arrow_metadata::PLENORA_FIELD_ID_KEY);
                        if let Some(id) = original {
                            metadata.insert(
                                plenora_core::contract::arrow_metadata::PLENORA_FIELD_ID_KEY,
                                id.clone(),
                            );
                        }
                    }
                    field.as_ref().clone().with_metadata(metadata)
                })
                .collect::<Vec<_>>();
            let primary = interno
                .active_geometry_column()
                .map(|g| interno.schema.index_of(&g.name))
                .transpose()?;
            let schema = Schema::new_with_metadata(fields, interno.schema.metadata().clone());
            let pubblicato = plenora_core::contract::arrow_schema::pubblica_schema_con_cursore(
                &schema,
                primary,
                &identita_osservate,
                &identita_ambigue,
                &mut prossima_identita,
            )
            .map_err(|errore| nel_passo_o_input(&format!("output `{nome}`"), errore))?;
            schemi_uscita.insert(nome.clone(), pubblicato);
        }
